\begin{lemma}[Induction from coordinate sectors]\label{lem:sector-induction}
Let a finite group $G$ act transitively on a finite set $\Omega$.
Suppose a $G$-module has a direct-sum decomposition
$T=\bigoplus_{A\in\Omega}T_A$ with $gT_A=T_{gA}$.
Fix $D\in\Omega$, let $H$ be its stabilizer, and take $z\in T_D$.
If $A_0=\C[H]z$, then the map
\begin{equation}\label{band:induced-map}
 \Phi:\C[G]\otimes_{\C[H]}A_0\longrightarrow\C[G]z,
 \qquad g\otimes a\longmapsto ga
\end{equation}
is an isomorphism of $G$-modules.
\end{lemma}

\begin{proposition}[Band quotient]\label{prop:band-quotient}
For the parameters in \Cref{band:sets}, there is a surjective
$G_m$-equivariant map
\begin{equation}\label{band:quotient}
 W_m\twoheadrightarrow
 \Ind_{S_D\times S_F}^{S_{B_m}}(W_h\boxtimes U_{m,s}).
\end{equation}
In particular, every irreducible constituent of the induced module on
the right is a constituent of $W_m$.
\end{proposition}

\begin{theorem}[Cyclic staircase support]
\label{thm:cyclic-saxl}
For every $m\ge1$ and every partition $\lambda\vdash N_m$, the irreducible
$S^\lambda$ occurs in $W_m$.
\end{theorem}

\begin{proposition}
\label{prop:dominated}
If $m\ge1$, $\lambda\vdash N_m$, and $\rho_m\unrhd\lambda$, then
$S^\lambda$ occurs in $W_m$.
\end{proposition}

\begin{lemma}[Path contraction]\label{path:contraction}
For arbitrary $X_1,\ldots,X_K\in\Mat_2(\C)$,
\begin{equation}\label{path:contraction-formula}
 \left\langle u,X_1\otimes\cdots\otimes X_K\right\rangle
 =(-1)^{m-1}
 \left[X_1\adj(X_2)X_3\adj(X_4)\cdots
                 X_{K-2}\adj(X_{K-1})X_K\right]_{11}.
\end{equation}
\end{lemma}

\begin{lemma}[Segment alternation]\label{path:segment}
Let $e$ be the number of even positions among $p,\ldots,p+r-1$, and put
$\delta=1$ if $p$ is even and $\delta=0$ otherwise. Then
\begin{equation}\label{path:segment-formula}
 A_{r,p}=r!(-1)^{e-\delta}M_1\cdots M_r.
\end{equation}
In particular, all these matrices are invertible. Their values are
\begin{equation}\label{path:segment-table}
 \begin{array}{c|cc}
 r & p\text{ odd} & p\text{ even}\\ \hline
 1&I&I\\
 2&-2Z&2Z\\
 3&-6J&-6J\\
 4&-24I&24I
 \end{array}
\end{equation}
\end{lemma}

\begin{proposition}[Four-row support of the width-two band]\label{prop:two-band}
For every $m\geq3$ and every partition $\eta\vdash 2m-1$ with
$\len(\eta)\leq4$, the irreducible module $S^\eta$ occurs in $U_{m,2}$.
\end{proposition}

\begin{lemma}[Alternating blocks as polytabloids]\label{lem:polytabloid}
Define $\theta_i=\#\{A\in L:|A|\ge i\}$, so that the block sizes are
the column lengths of $\theta$.  Then
$\C[S_B]v_L\cong S^\theta$.
The same assertion holds for any ordered basis of a dual vector space.
\end{lemma}

\begin{lemma}[Pieri rule]\label{lem:pieri}
For $\nu\vdash a$ and $b\ge0$,
\begin{equation}\label{tools:pieri}
 \Ind_{S_a\times S_b}^{S_{a+b}}
      (S^\nu\boxtimes\mathbf1)
 \cong
 \bigoplus_{\substack{\lambda\vdash a+b,\ \lambda\supseteq\nu\\
                      \lambda/\nu\text{ a horizontal strip}}}
       S^\lambda.
\end{equation}
Every summand occurs once.
\end{lemma}

\begin{theorem}[Elementary positivity and a permutation witness]
\label{main:theorem}
There is a deterministic terminating procedure which, given a natural
unit interval graph $G$ on $[n]$ and $\sigma\in D_G^0$, returns a partition
$\theta_G(\sigma)\vdash n$ such that
\begin{equation}
 \chi_G(X;q)=\sum_{\sigma\in D_G^0}
       q^{\ginv_G(\sigma)}e_{\theta_G(\sigma)}(X).
 \label{main:witness}
\end{equation}
In particular every elementary coefficient of $\chi_G(X;q)$ belongs to
$\N[q]$. The assertion holds as a formal symmetric-function identity,
uniformly in $n$ and $G$.
\end{theorem}

\begin{lemma}[Insertion digits]
\label{graph:digits}
There is a bijection between $\mathcal A_G$ and the sequences
$(j_1,\ldots,j_n)$ with $0\le j_a\le l_a$. Under this bijection,
$\inv_G(w)=\sum_a j_a$. Reversal is a bijection
$D_G^0\to\mathcal A_G$, and
\begin{equation}
 \inv_G(\operatorname{reverse}\sigma)=M-\ginv_G(\sigma).
 \label{graph:reverse}
\end{equation}
\end{lemma}

\begin{proposition}[Commuting independent-set sums]
\label{graph:commutation}
For every natural unit interval graph $\Gamma$ and all $j,k\ge0$,
$E_j(\Gamma)E_k(\Gamma)=E_k(\Gamma)E_j(\Gamma)$.
\end{proposition}

\begin{proposition}[Coloring kernel]
\label{graph:kernel}
If $\alpha(\Gamma)\le D$, then $X_G(X;q)$ is symmetric and
\begin{equation}
 X_G(X;v^2)=\sum_{\substack{\lambda\vdash n\\\ell(\lambda)\le D}}
       v^M[X_u]m_\lambda(Y)\,e_\lambda(X).
 \label{graph:coefficient}
\end{equation}
The equality is independent of the extra vertices of $\Gamma$.
\end{proposition}

\begin{lemma}[Color reversal and shape reciprocity]
\label{graph:reciprocity}
For every natural unit interval graph $G$, $X_G(X;q)=\chi_G(X;q)$.
Writing $c_\lambda(q)=[e_\lambda]X_G(X;q)$, one has
\begin{equation}
 c_\lambda(q)=q^M c_\lambda(q^{-1})
 \label{graph:reciprocity-eq}
\end{equation}
for every partition $\lambda$.
\end{lemma}

\begin{lemma}[Ordered decomposition]\label{alg:ordered}
Choose graded vector-space sections $B_d\to S_d$ of all quotient
maps.  For every $d$, multiplication induces a vector-space
isomorphism
\begin{equation}\label{alg:ordered-sum}
 S_d\cong
 \bigoplus_{\substack{d^{(1)}+\cdots+d^{(m)}=d\\
       \mu(d^{(1)})>\cdots>\mu(d^{(m)})}}
 B_{d^{(1)}}\otimes\cdots\otimes B_{d^{(m)}},
\end{equation}
with the polynomial-degree shifts prescribed by the shuffle kernels.
\end{lemma}

\begin{lemma}[Restrictions on a slope]\label{alg:restrictions}
If all $r_\ell$ have the slope of $d$,
Equation~\eqref{alg:restriction-S} factors through a map
\begin{equation}\label{alg:restriction}
 R_P^z:B_d\longrightarrow
       \left(\bigotimes_\ell B_{r_\ell}\right)[z].
\end{equation}
These maps compose under refinement, with the successive centers
added.  When a same-slope product is restricted, only splits whose
nonempty subgroups have this slope survive; the restrictions of its
two factors may already be taken in their respective quotients.
\end{lemma}

\begin{lemma}[Polynomial symbols and detection]\label{alg:detection}
Every $L_P(f)$ is polynomial in its centers.  The maps $L_P$ jointly
inject $\gr_wB_d$ into their polynomial targets.  For the additive
tensor filtration
\begin{equation}\label{alg:tensor-filtration}
 \cF_w(B_a\otimes B_b)
    =\sum_{u+v\ge w}\cF_uB_a\otimes\cF_vB_b,
\end{equation}
tensor products of the restriction tests characterize membership,
and tensor products $L_R\otimes L_S$ jointly detect its associated
grades.
\end{lemma}

\begin{lemma}[Product symbols]\label{alg:product-symbol}
The same-slope product preserves the sum of filtration weights.
For $f\in\gr_uB_d$, $g\in\gr_vB_e$, and
$R=(r_1,\ldots,r_m)$, its leading symbols satisfy
\begin{equation}\label{alg:product-symbol-formula}
 L_R(f*g)=
 \sum_{\substack{r_i=d_i'+e_i'\\
                  \sum_i d_i'=d,\ \sum_i e_i'=e}}
 (-1)^{\sum_{i>j}\chi(d_i',e_j')}
 (*^{\otimes R})
 \bigl(L_{(d_i')}(f)\otimes L_{(e_i')}(g)\bigr).
\end{equation}
All nonzero entries in this sum have slope $\theta$; zero entries in
a list of symbols are omitted.  The operator $*^{\otimes R}$ places
the two factors belonging to each target group next to each other,
without a sign, and applies its shuffle product.
\end{lemma}

\begin{proposition}\label{alg:bialgebra}
With $\Delta=\sum_{a+b=d}\Delta_{a,b}$,
$\mathcal H$ is a connected dimension-graded bialgebra, and its
coproduct is cocommutative with the interchange sign
$\varepsilon(a,b)$.
\end{proposition}

\begin{lemma}[Signed vector-space PBW]\label{alg:pbw}
Symmetrized multiplication gives an isomorphism of graded vector
spaces
\begin{equation}\label{alg:pbw-map}
 \operatorname{Sym}_{\varepsilon}(\mathcal P)
       \longrightarrow\mathcal H.
\end{equation}
Here the left side is the signed symmetric vector space: exchanging
homogeneous vectors of dimensions $a,b$ multiplies a tensor by
$\varepsilon(a,b)$.  The gradings retained are dimension, original
shifted degree, and filtration weight; tensor length is summed over.
\end{lemma}

\begin{lemma}[The unit normalization and positive crossing]
\label{wall:unit}
For $j\ge0$,
\begin{equation}
 [X_{jp}]D_p=
 \frac{v^{-j^2}}{\prod_{i=1}^j(1-v^{-2i})}.
 \label{wall:unit-coefficient}
\end{equation}
Let $t=\Omega(a,m)$.  Then
\begin{equation}
 \Ad(U_{a,k,f})X_m
 =X_m\frac{U_{a,k,f}(v^{2t}X_a)}{U_{a,k,f}(X_a)}.
 \label{wall:unit-ratio}
\end{equation}
For $t>0$ the ratio is $\prod_{\ell=1}^t f(v^{k+2\ell}X_a)$.
For $t<0$ the inverse adjoint has ratio
$\prod_{\ell=t+1}^{0}f(v^{k+2\ell}X_a)$.
Thus $\Ad(U_{a,k,f})^\varepsilon X_m$ has nonnegative integral
Laurent-series coefficients whenever $\varepsilon t\ge0$.
Its constant, or no-jump, coefficient is one.
\end{lemma}

\begin{theorem}[Positive sections]
\label{wall:positivity}
Every $\Theta_m$ has coefficients in $\N((v^{-1}))$ in every
chamber.  More generally, the same is true of a section $F$ all
of whose incoming coefficients belong to $\N((v^{-1}))$.
\end{theorem}

\begin{corollary}[Positive products]
\label{wall:product}
The structure coefficients in
\[
 \Theta_{m_1}\cdots\Theta_{m_b}
 =\sum_n A_n(\Theta_{m_1}\cdots\Theta_{m_b})\Theta_n
\]
belong to $\N((v^{-1}))$.  Products and expansions are locally
finite at every specified exponent.
\end{corollary}

\begin{lemma}[Finite support in each $p$-fiber]
\label{wall:fiber-bound}
On the open side $\operatorname{sign}h(p)=\sigma$, a non-pure
root $kp+u$ occurring in a wall element or its logarithm satisfies
\begin{equation}
 0\le k\le M_\sigma(u).
 \label{wall:fiber-bound-equation}
\end{equation}
The pure $p$-wall has element $D_p$ everywhere on the cut where
no other wall direction is present.
\end{lemma}

\begin{theorem}[Change of chart]
\label{wall:mutation}
The wall system for $C$, with simple data $D_c$, is carried
to the wall system for $C'$, with simple data $D_{c'}$, as
follows.  Off the cut $p^\perp$, use the covector map $T$
from \eqref{wall:piecewise-mutation} and act on exponents
by $L_\sigma$ on the side of sign $\sigma$.  On the cut,
replace the pure wall by $D_{-p}$.

Suppose $F$ and $F'$ are sections specified by finite Laurent
polynomials in the respective all-negative chambers, and
these initial polynomials satisfy the rational identity
\begin{equation}
 F=\Ad(D_p)F'.
 \label{wall:initial-comparison}
\end{equation}
For $h(p)>0$ their transported values agree coefficientwise
under the identity; for $h(p)<0$ they agree coefficientwise
under $S$.  In particular,
\begin{equation}
 A_n(F)=A_{\mu_p(n)}(F'),\qquad
 \mu_p(n)=n+[-\Omega(p,n)]_+p.
 \label{wall:incoming-mutation}
\end{equation}
The map $\mu_p:M\to M$ is a bijection.
\end{theorem}

\begin{lemma}[Embedding]\label{tri:embedding}
Every naturally labeled unit interval graph on $n$ vertices occurs as
an ordered induced subgraph on $n$ selected bridges of a triangular
chart.  The times and phases may all be chosen rationally.
\end{lemma}

\begin{lemma}[Polynomial comparison under rotation]\label{tri:rotation-comparison}
Let $Y'$ be the alphabet after one rotation.  For every symmetric
polynomial $P$,
\begin{equation}\label{tri:polynomial-comparison}
 P(Y)=\Ad(D_p)P(Y').
\end{equation}
Both sides are finite Laurent polynomials, so the actual incoming
coefficients satisfy
\begin{equation}\label{tri:incoming-rotation}
 A_m(P(Y))=A_{m+[-\Omega(p,m)]_+p}(P(Y')).
\end{equation}
\end{lemma}

\begin{lemma}[Pure coefficient extraction]\label{tri:pure}
Let $P$ be a homogeneous symmetric polynomial of degree $N$, and let
$m=\sum_i\mu_i d_i$ with
$\mu_1\geq\cdots\geq\mu_D\geq0$ and $\sum_i\mu_i=N$.
For commuting indeterminates $z_1,\ldots,z_D$,
\begin{equation}\label{tri:pure-formula}
 A_m(P(Y))=[z_1^{\mu_1}\cdots z_D^{\mu_D}]P(z_1,\ldots,z_D).
\end{equation}
\end{lemma}

\begin{lemma}\label{tri:linear}
In the all-negative chamber of the triangular chart,
\[
 U=\Theta_{d_1}.
\]
\end{lemma}

\begin{lemma}[Vertex support before subtraction]\label{tri:domination}
For every partition $\mu\vdash N$ with at most $D$ parts, padded by
zeroes, put $x_\mu=\sum_i\mu_i d_i$.  In the all-negative chamber,
$\Theta_{x_\mu}$ has nonnegative vertex exponents and coefficients
in $\N[v,v^{-1}]$, and is a finite Laurent polynomial.  More
precisely, coefficientwise in both vertex exponents and $v$,
\begin{equation}\label{tri:positive-domination}
 \frac{N!}{\prod_i\mu_i!}\,\Theta_{x_\mu}\ \leq\ U^N.
\end{equation}
\end{lemma}

\begin{theorem}[Monomial sections]\label{tri:monomial}
For every partition $\lambda$ with at most $D$ parts, padded by
zeroes to length $D$, one has in the all-negative chamber
\begin{equation}\label{tri:monomial-identity}
 m_\lambda(Y)=\Theta_{\sum_{i=1}^D\lambda_i d_i}.
\end{equation}
In particular,
\begin{equation}\label{tri:elementary-identity}
 E_k=\Theta_{d_1+\cdots+d_k}\qquad(0\leq k\leq D).
\end{equation}
\end{theorem}

\begin{proposition}[Packet switch]
\label{route:switch}
There is a computable energy-preserving bijection
\begin{equation}
 \label{route:switch-equation}
 \left\{\text{product states of exponent $y$ in $II$}\right\}
 \longleftrightarrow
 \left\{\begin{array}{c}
  \text{product states of exponent $z$ in $I$, together with}\\
  \text{a decorated jump of $W$ from $z$ to $y$}
 \end{array}\right\}.
\end{equation}
On the right the energy is the state energy plus the jump energy.
If $\Omega(p,y)=0$, the total jump is always the unique zero jump.
\end{proposition}

\begin{proposition}[Formal degree bounds]
\label{route:parity}
For every partition $\mu\vdash N$, histories in $T_{x_\mu}$ have
\begin{equation}
 \label{route:parity-range}
 -M\leq E(t)\leq M,\qquad E(t)\equiv M\pmod 2.
\end{equation}
Consequently $T_{x_\mu}$ is finite, and
$v^M[X_u]\Theta_{x_\mu}^{H_-}$ belongs to $\N[q]$ with $q=v^2$
and degree at most $M$.
\end{proposition}

\begin{theorem}[Permutation witness]
\label{route:witness}
For every naturally labeled unit interval graph $G$, the preceding
finite rule assigns a partition $\Lambda_G(w)\vdash n$ to each
$w\in\mathcal A_G$ and satisfies the formal polynomial identity
\begin{equation}
 \label{route:witness-identity}
 X_G(X;q)=\sum_{w\in\mathcal A_G}
                   q^{\inv_G(w)}e_{\Lambda_G(w)}(X).
\end{equation}
In particular, every elementary coefficient is in $\N[q]$ and has
degree at most $|E(G)|$.
\end{theorem}

\begin{proposition}[Disjoint-pair interaction]\label{dis:interaction}
For disjoint vertex pairs $a,b$ and every real function $f$ on
$\Omega_d$,
\begin{equation}\label{dis:bound}
  2\langle h_a f,h_b f\rangle
  \ge 2\|g_{a,b}f\|^2
       -\|R_{a,b}f\|^2-\|R_{b,a}f\|^2.
\end{equation}
\end{proposition}

\begin{proposition}\label{mix:global}
The pair-resampling operator satisfies
\begin{equation}\label{mix:H-square}
H^2\succeq H.
\end{equation}
\end{proposition}

\begin{lemma}\label{mix:connectivity}
Any two graphs in $\Omega_d$ can be joined by a sequence of valid switches.
\end{lemma}

\begin{corollary}\label{mix:poincare}
The kernel of $H$ consists exactly of the constant functions. For every
real function $f$ on $\Omega_d$,
\begin{equation}\label{mix:H-poincare}
\operatorname{Var}_{\pi_d}(f)\le \langle f,Hf\rangle.
\end{equation}
\end{corollary}

\begin{lemma}\label{mix:comparison}
The operators above satisfy
\begin{equation}\label{mix:comparison-bounds}
h_a\preceq n^2J_a,\qquad
\sum_{a\in\binom V2}J_a=2L,\qquad
H\preceq2n^2L.
\end{equation}
\end{lemma}

\begin{lemma}[Fixed block sizes]\label{row:fixed-blocks}
Let $(U_1,U_2,U_3)$ and $(W_1,W_2,W_3)$ be independent uniform ordered
partitions of finite labeled sets $U$ and $W$, with all six block sizes
prescribed.  For arbitrary real functions $g_i=g_i(U_i,W_i)$,
\begin{equation}\label{row:fixed-variance}
 \operatorname{Var}\Bigl(\sum_{i=1}^3 g_i\Bigr)
 \le 2\sum_{i=1}^3\operatorname{Var}(g_i).
\end{equation}
\end{lemma}

\begin{lemma}[Three-row variance inequality]\label{row:variance}
Fix row and column sums for binary matrices with three rows, and take
the uniform distribution on the nonempty set of all matrices with
these prescribed margins.
Let $S_i$ denote row $i$.  For arbitrary real row functions $f_i$,
\begin{equation}\label{row:main-variance}
 \operatorname{Var}\Bigl(\sum_{i=1}^3f_i(S_i)\Bigr)
 \le 2\sum_{i=1}^3\operatorname{Var}(f_i(S_i)).
\end{equation}
\end{lemma}

\begin{lemma}[Equality-indicator projections on a slice]
\label{sl:comparison}
Let $N\ge0$ and $0\le q\le N$ be integers. Give
\[
 \mathcal X_{N,q}
 =\left\{x\in\{0,1\}^N:\ \sum_{i=1}^N x_i=q\right\}
\]
the uniform measure. Let $\tau_{ij}$ interchange coordinates $i,j$, and
put
\[
 G=\frac12\sum_{i<j}(I-\tau_{ij}).
\]
For each pair $i<j$, let $Q_{ij}$ be orthogonal projection onto the centered
function
\[
 z_{ij}=\mathbf 1_{\{x_i=x_j\}}
            -\mathbb P(x_i=x_j),
\]
with the convention $Q_{ij}=0$ when $z_{ij}=0$. Then
\begin{equation}
 S:=\sum_{i<j}Q_{ij}\preceq G.
 \label{sl:operator-comparison}
\end{equation}
\end{lemma}

\begin{corollary}[Summed equality-indicator energy]
\label{sl:global}
For every vertex pair $a$ and every function $f$ on the graph space,
\begin{equation}
 \sum_{b:\,b\cap a=\varnothing}\|R_{a,b}f\|^2
 \le
 \sum_{b:\,b\cap a=\varnothing}\|g_{a,b}f\|^2.
 \label{sl:graph-comparison}
\end{equation}
\end{corollary}

\begin{corollary}\label{dis:nonnegative}
The ordered sum
\begin{equation}\label{dis:D}
 D=\sum_{\substack{a,b\in\binom V2\\a\cap b=\varnothing}}h_a h_b
\end{equation}
is self-adjoint and positive semidefinite.
\end{corollary}

\begin{proposition}\label{tri:gap}
For every vertex triple $T$, one has $H_T^2\succeq H_T$.
\end{proposition}

\begin{proposition}[The balance bound]
\label{prop:balance-four}
Assume $M\ge9$, and let $h_1\ge h_2\ge\cdots$ be the column
heights of $\nu\vdash n$.  If
\begin{equation}
 \sum_{i=1}^4 h_i\le2M-2,
 \label{bal:four-small}
\end{equation}
then $S^\nu$ occurs in $S^L\otimes S^L$.
The same conclusion holds if Equation~\eqref{bal:four-small}
holds for the column heights of $\nu^t$.
\end{proposition}

\begin{lemma}[Triangle quotient]\label{band:triangle-quotient}
There is a quotient of $W_L$ isomorphic to
\begin{equation}\label{eq:band-triangle-quotient}
 \Ind_{S_D\times S_F}^{S_B}
       (W_{M-2}\boxtimes U_F),
\end{equation}
where $W_{M-2}$ is the specified cyclic module in
Theorem~\ref{thm:cyclic-input}.  The module $U_F$ is generated by
the row and column block alternations on $F$, using an initial
alphabet on every remaining block.
Consequently, it suffices to find a diagram $\mu\subseteq\lambda$
of size $|F|$ such that $S^\mu$ occurs in $U_F$.
\end{lemma}

\begin{lemma}[Separated contraction]\label{band:separated}
Retain from $u_F$ only terms using $P$ on the path, $X_+$ on $E_+$,
and $X_-$ on $E_-$.  The resulting tensor is, up to one nonzero
overall sign,
\begin{equation}\label{eq:band-separated}
 u_{\mathrm{path}}\otimes z_+\otimes z_-.
\end{equation}
Here $u_{\mathrm{path}}$ is the product of the two path block
alternations, with both endpoint singleton letters equal to one.
The tensors $z_+,z_-$ are the row-column alternating generators
for the two copies of $E$, with the long-block index shifted by two
and the two tensor layers interchanged for $E_-$.
\end{lemma}

\begin{lemma}[Two extra copies]\label{band:two-extras}
The cyclic span of $z_+\otimes z_-$ on $E_+\sqcup E_-$ contains
every diagram $\eta\vdash 2r$ whose column heights are even and
whose number of columns is at most eight.
\end{lemma}

\begin{lemma}\label{lem:candidate}
The parameters satisfy
\begin{equation}\label{eq:r-bounds}
 r\le\begin{cases}(M-1)/2,&M\text{ odd},\\3M/2+2,&M\text{ even}.
 \end{cases}
\end{equation}
For $M\ge9$, the partition with column lengths
\begin{equation}\label{eq:candidate}
 L=(M+b+s-1,\ M-1+b,\ M-2,M-3,\ldots,3,\ 2^{b+1},\ 1^s)
\end{equation}
is self-conjugate and has size $n$. Consequently the support of
$S^L\otimes S^L$ is invariant under transposition of the target.
If no parity-compatible $M\ge9$ is available, then $n\le64$.
\end{lemma}

\begin{lemma}
\label{lem:capacity-rectangle}
Let $i,j\ge1$. If $H_i\le U$ and $W_j\le V$, then
\begin{equation}
 n\le\max\left(U+V-1,
              \left\lfloor\frac{UV}{ij}\right\rfloor\right).
 \label{eq:capacity-rectangle}
\end{equation}
\end{lemma}

\begin{lemma}
\label{lem:capacity-large}
If $M\ge22$, a target satisfying
Equation~\eqref{eq:capacity-four-assumption} passes the band test in
one of its two orientations.
\end{lemma}

\begin{lemma}
\label{lem:capacity-intermediate}
The first-four balance test and the band tests cover every target
when $9\le M\le21$, $r>0$, except possibly for
\begin{equation}
 (M,r)\in
 \{(10,8),\ldots,(10,17)\}
 \cup\{(12,14),\ldots,(12,20)\}
 \cup\{(14,22),(14,23)\}.
 \label{eq:capacity-exceptions}
\end{equation}
\end{lemma}

\begin{lemma}
\label{lem:capacity-prefix-pruning}
Let $A$ be a nonempty multiset of positive integers with total $N$, and let
$a=(a_1,\ldots,a_l)$ be a nonempty prefix of the column-height list
of a partition of $N$. If
\begin{equation}
 \min\left(N,\sum_{v=1}^{\min(i,l)}a_v+(i-l)_+a_l\right)
 \le P_A(i)\qquad(1\le i<\max A),
 \label{eq:capacity-prefix-bound}
\end{equation}
then every completion of $a$ has the support associated with $A$.
For a complete column-height list followed by a zero, these inequalities
are equivalent to that support condition.
\end{lemma}

\begin{lemma}
\label{lem:capacity-hit}
If the code returns \texttt{hit(h)=True} on a complete column-height
list followed by zero, the target is supplied by the big pair and
the other balance components.
\end{lemma}

\begin{lemma}
\label{lem:capacity-enumeration}
For each pair in Equation~\eqref{eq:capacity-exceptions}, the
procedure \texttt{gen} exhausts all targets, up to transposition and
the already justified pruning conditions.
\end{lemma}

\begin{proposition}
\label{prop:capacity-exhaustion}
For every admissible $M\ge9$ and $r>0$, every target partition of
$n=N_M+2r$ is supplied by the band and balance constructions for
$L$.
\end{proposition}

\begin{lemma}[Young support]\label{lem:young-support}
For a finite list $A$ of positive integers of sum $n$, the module
$\Ind_{\prod_{a\in A}S_a}^{S_n}\mathbf1$ contains exactly the
$S^\nu$ whose column heights $h_1\ge h_2\ge\cdots$ satisfy
\begin{equation}\label{eq:young-prefix}
 \sum_{j=1}^k h_j\le P_A(k):=\sum_{a\in A}\min(k,a)
 \qquad(k\ge1).
\end{equation}
The constituent indexed by the decreasing rearrangement of $A$
has multiplicity one. A component containing every shape of total
$t$ with at most $j$ rows contains the support of the induced-trivial
module corresponding to a balanced division of $t$ into $j$ parts.
\end{lemma}

\begin{theorem}[Cyclic staircase support, {\cite[Theorem~3.1]{SaxlCyclic}}]
\label{thm:cyclic-input}
For every $m\ge1$ and every $\alpha\vdash N_m$, the irreducible
$S^\alpha$ occurs in the particular cyclic module $W_m$ of
\eqref{eq:cyclic-generator}.
\end{theorem}

\begin{theorem}[Logical hole bound]
\label{thm:logical-hole-bound}
Let $\lambda$ be balanced, let $B$ be its bottleneck similarity, and set
\[
 D_0=10^8(n+1)^4.
\]
For every even set $U\subseteq V$,
\begin{equation}
\label{eq:logical-hole-bound}
 g_\lambda(U)\Phi_B(U)\le 2D_0^{|U|/2}.
\end{equation}
\end{theorem}

\begin{lemma}[Four-hole inequality]
\label{lem:four-holes}
For any positive activities $\mu$ and four distinct vertices $a,b,c,d$,
\[
 g_\mu(abcd)\le
 g_\mu(ab)g_\mu(cd)+g_\mu(ac)g_\mu(bd)
                         +g_\mu(ad)g_\mu(bc).
\]
Consequently, if every row maximum is at most $4$, then
\begin{equation}
\label{eq:small-hole-bounds}
 g_\mu(\varnothing)=1,\qquad
 g_\mu(U)\le4\quad(|U|=2),\qquad
 g_\mu(U)\le48\quad(|U|=4).
\end{equation}
\end{lemma}

\begin{lemma}[Relocating a hole along a strong path]
\label{lem:hole-relocation}
Let $B$ be defined by \eqref{eq:bottleneck}, and suppose that
$\mu_e\ge\lambda_e$ for every edge and
\[
 \frac18\le r_i(\mu)\le4\qquad(i\in V).
\]
If $|U|\in\{2,4\}$ and $i,j\in U$ are distinct, then
\begin{equation}
\label{eq:hole-relocation-bound}
 g_\mu(U)\le\frac{10^5n}{B_{ij}}.
\end{equation}
\end{lemma}

\begin{proposition}[Marked matching laws]\label{prop:marked-laws}
For arbitrary positive logical activities, sample from the bag matching
law and reveal the edge portions as above. The all-real event has
probability $1/I$;
conditional on this event, the decoded logical matching has law
$\pi_\lambda$. For each logical edge $uv$,
\begin{equation}\label{eq:probe}
 \Prb(\text{probe for }uv\text{ is used and all other edges are real})
 =\frac{g_\lambda(uv)}{DI}.
\end{equation}
Conditional on this event, the residual logical matching has the
$\lambda$-weighted perfect-matching law on the vertices other than
$u,v$.
\end{proposition}

\begin{proposition}[Bounded inflation]\label{prop:bag-inflation}
If the logical activities are balanced, then
\begin{equation}\label{eq:inflation}
 1\le I\le2.
\end{equation}
\end{proposition}

\begin{lemma}\label{lem:deletion-accounting}
If an even hole set $U$ has a real completion, then $R$ is even,
$|R|\le|U|$, and
\begin{equation}\label{eq:deletion-identity}
 Z'(-U)
 =C_0 F(U)
 Z_\lambda\bigl(-R;E_{\mathrm{br}}(U)\text{ forbidden}\bigr).
\end{equation}
In particular,
$g'(U)\le F(U)g_\lambda(R)$.
\end{lemma}

\begin{lemma}[Pairings in a hierarchy]
\label{lem:ultrametric-pairing}
Let $B\ge1$ be a symmetric similarity on a finite vertex set $X$,
satisfying $B_{ij}\ge\min\{B_{ik},B_{kj}\}$. Let $\mathcal C_t$ be
the equivalence classes of $B\ge t$, including singletons.
For every even set $U\subseteq X$,
\begin{equation}
\label{eq:threshold-pairing}
 \log\Phi_B(U)
 =\int_1^\infty\sum_{C\in\mathcal C_t}
       \left\lfloor\frac{|C\cap U|}{2}\right\rfloor\frac{dt}{t}.
\end{equation}
There is one pairing that attains the maximum number of internal pairs
in every threshold class simultaneously.
\end{lemma}

\begin{lemma}\label{lem:lifted-hole-bound}
If the logical activities are balanced, then for every even set
$U$ of enlarged vertices,
\[
 g'(U)\Phi_{B'}(U)\le2D_0^{|U|/2}.
\]
More precisely, for every $U$ with a real completion, the deterministic
quantities above satisfy
\begin{equation}\label{eq:threshold-charge}
 F(U)\Phi_{B'}(U)\le\Phi_B(R).
\end{equation}
\end{lemma}

\begin{theorem}[Pair energy inequality]
\label{thm:pair-energy}
For every two real functions $f_1,f_2$ on $\calM$,
\begin{equation}
\label{eq:pair-energy}
 \Var_\pi f_1\le L\,
 \calE\bigl((A,B)\mapsto f_1(A)+f_2(B)\bigr).
\end{equation}
The same constant works for every common-interval clamp of the
reference activities.
\end{theorem}

\begin{lemma}[Elementary energy bounds]
\label{lem:elementary-pair-energy}
With the notation above,
\begin{align}
 \sum_A\pi(A)\sum_{A'\in\mathcal S(A)}
       (f_1(A)-f_1(A'))^2
 &\le60N^2A_0^2 E,
 \label{eq:safe-switch-energy}\\
 \sum_A\pi(A)\sum_{A'\in\mathcal K(A)}
       (f_1(A)-f_1(A'))^2
 &\le12NA_0 E,
 \label{eq:color-energy}\\
 \sum_{A,B}\pi(A)\pi(B)\sum_{C\in\mathcal C(A,B)}
       \bigl(F(A,B)-F((A,B)^C)\bigr)^2
 &\le6NE.
 \label{eq:cycle-energy}
\end{align}
Here $\mathcal C(A,B)$ denotes the discrepancy cycles, and $(A,B)^C$
is the pair after swapping $C$.
\end{lemma}

\begin{lemma}[Cell identity and cancellation]
\label{lem:cell-identity}
The quantities just defined satisfy
\begin{equation}
\label{eq:single-cell-identity}
 D_C=\Delta+\sum_{J\in P}g_J-\sum_{J\in Q}g_J+E_P-E_Q
\end{equation}
for each cell.  Consequently,
\begin{equation}
\label{eq:global-cell-identity}
 D_C=\sum_{\text{cells of }C}(\Delta+E_P-E_Q).
\end{equation}
\end{lemma}

\begin{lemma}[Swap sum]
\label{lem:swap-sum}
The sum in \eqref{eq:swap-sum} satisfies $\Sigma_{\rm swap}\le12N^2E$.
\end{lemma}

\begin{lemma}\label{lem:replica-gap}
The lazy product chain has spectral gap at least $3/(8M)$, and hence
at least $1/(20LM)$. The dependence on $L$ in the stronger bound
is carried by $q=32L$, and hence by $M$.
\end{lemma}

\begin{lemma}\label{lem:one-pass-scaling}
Suppose $G$ is symmetric and $\alpha\le G_{ij}\le3$ for $i\ne j$.
Initialize $v_i=2$ for every vertex and visit the vertices in their
fixed order, setting
\begin{equation}\label{eq:scale-update}
 v_i\leftarrow\max_{j\ne i}\frac{G_{ij}}{v_j}.
\end{equation}
Every coordinate only decreases, all final coordinates lie in
$[\alpha/2,2]$, and the final vector satisfies
$v_i v_j\ge G_{ij}$ with an equality in every row.
\end{lemma}

\begin{lemma}\label{lem:successful-stage}
Suppose the current logical activities are balanced and every empirical
mean is within $\sigma$ of its exact mean. Then the next scaled
activities are balanced and
\begin{equation}\label{eq:stage-relative-error}
 \left|\frac{\widehat R}{R}-1\right|
 \le10\sigma\le\frac\eps{100K}.
\end{equation}
\end{lemma}
